1	use crate::actions::Target;
2	use crate::cards::{ActivatedAbilityDef, CardBehavior, CardData, CardRegistry, SacrificeCost,
3	                   TriggerKind, TriggeredAbilityDef};
4	use crate::ids::ObjectId;
5	use crate::state::{GameState, PendingEffect};
6	use crate::types::*;
7	
8	/// Grimgrin, Corpse-Born {3}{U}{B} 5/5 Legendary Zombie Warrior.
9	/// Grimgrin enters tapped and doesn't untap during your untap step.
10	/// Sacrifice another creature: Untap Grimgrin and put a +1/+1 counter on it.
11	/// Whenever Grimgrin attacks, destroy target creature defending player controls,
12	/// then put a +1/+1 counter on Grimgrin.
13	pub struct GrimgrinCorpseBorn;
14	
15	impl CardBehavior for GrimgrinCorpseBorn {
16	    fn card_data(&self) -> CardData {
17	        CardData {
18	            name: "Grimgrin, Corpse-Born".into(),
19	            cost: Some(ManaCost::new(vec![
20	                ManaSymbol::Generic(3),
21	                ManaSymbol::Colored(Color::Blue),
22	                ManaSymbol::Colored(Color::Black),
23	            ])),
24	            card_types: vec![CardType::Creature],
25	            supertypes: vec![Supertype::Legendary],
26	            subtypes: vec!["Zombie".into(), "Warrior".into()],
27	            power: Some(5),
28	            toughness: Some(5),
29	            oracle_text: "Grimgrin, Corpse-Born enters tapped and doesn't untap during your untap step.\nSacrifice another creature: Untap Grimgrin and put a +1/+1 counter on it.\nWhenever Grimgrin attacks, destroy target creature defending player controls, then put a +1/+1 counter on Grimgrin.".into(),
30	            keywords: vec![],
31	            flashback_cost: None,
32	            continuous_effects: vec![
33	                ContinuousEffect::PreventUntap {
34	                    scope: EffectScope::OnSelf,
35	                },
36	            ],
37	            additional_cost: None,
38	            triggered_abilities: vec![
39	                TriggeredAbilityDef {
40	                    kind: TriggerKind::Attacks,
41	                    description: "destroy target creature defending player controls, then +1/+1 counter".into(),
42	                },
43	            ],
44	        }
45	    }
46	
47	    fn on_resolve(&self, state: &mut GameState, object_id: ObjectId, _targets: &[Target], _registry: &CardRegistry) {
48	        state.move_object(object_id, Zone::Battlefield);
49	        // Enters tapped.
50	        if let Some(obj) = state.get_object_mut(object_id) {
51	            obj.tapped = true;
52	            obj.is_legendary = true;
53	        }
54	        state.log(crate::state::LogLevel::Event,
55	            "Grimgrin, Corpse-Born enters the battlefield tapped".into());
56	    }
57	
58	    fn activated_abilities(&self, state: &GameState, object_id: ObjectId, _registry: &CardRegistry) -> Vec<ActivatedAbilityDef> {
59	        match state.get_object(object_id) {
60	            Some(o) if o.zone == Zone::Battlefield => {}
61	            _ => return vec![],
62	        };
63	
64	        vec![ActivatedAbilityDef {
65	            ability_index: 0,
66	            description: "Sacrifice another creature: Untap Grimgrin, +1/+1 counter".into(),
67	            cost: ManaCost::free(),
68	            requires_tap: false,
69	            sacrifice_cost: SacrificeCost::SacrificeAnotherCreature,
70	            target_requirement: None,
71	            once_per_turn: false,
72	            sorcery_speed_only: false,
73	        }]
74	    }
75	
76	    fn on_activate_ability(&self, state: &mut GameState, object_id: ObjectId, _ability_index: usize, _targets: &[Target], _registry: &CardRegistry) {
77	        // The engine already sacrificed another creature as part of paying the cost.
78	        // Now untap Grimgrin and add a +1/+1 counter.
79	        if let Some(obj) = state.get_object_mut(object_id) {
80	            obj.tapped = false;
81	        }
82	        state.add_counters(object_id, CounterType::PlusOnePlusOne, 1);
83	        state.log(crate::state::LogLevel::Event,
84	            "Grimgrin: sacrificed creature, untapped, +1/+1 counter".into());
85	    }
86	
87	    fn on_attacks(&self, state: &mut GameState, self_id: ObjectId, _registry: &CardRegistry) {
88	        let controller = match state.get_object(self_id) {
89	            Some(o) if o.zone == Zone::Battlefield => o.controller,
90	            _ => return,
91	        };
92	
93	        // Get the defending player from combat state, falling back to opponent.
94	        let defender = state.combat.as_ref()
95	            .and_then(|c| c.attackers.get(&self_id).copied())
96	            .unwrap_or_else(|| state.opponent(controller));
97	
98	        // Collect creatures the defending player controls as potential targets.
99	        let targets: Vec<Target> = state.objects_in_zone(Zone::Battlefield, defender)
100	            .iter()
101	            .filter(|o| o.power.is_some())
102	            .map(|o| Target::Object(o.id))
103	            .collect();
104	
105	        // Per ruling: "If the defending player controls no creatures when Grimgrin attacks,
106	        // the last ability will be removed from the stack and have no effect."
107	        // This means no +1/+1 counter either.
108	        if targets.is_empty() {
109	            return;
110	        }
111	
112	        // Present target choice to the controller. The effect destroys the target
113	        // and then adds a +1/+1 counter to Grimgrin.
114	        crate::cards::helpers::present_target_choice(
115	            state,
116	            self_id,
117	            controller,
118	            targets,
119	            PendingEffect::DestroyThenCounter {
120	                source_id: self_id,
121	                source_name: "Grimgrin, Corpse-Born".into(),
122	            },
123	            "Grimgrin, Corpse-Born: destroy target creature defending player controls",
124	            false,
125	        );
126	    }
127	}
